//! # tapestry-core
//!
//! Shared contracts for the Tapestry programme: identity, sessions,
//! artefacts, reviews, telemetry and the TAP/1 protocol schema.
//!
//! This crate is deliberately free of I/O. It defines the data that moves;
//! the moving is someone else's job.
//!
//! Wire compatibility: every public type here is a contract consumed by
//! `tapestry-desktop` and `tapestry-android`. Changes require a versioned,
//! compatibility-checked schema change — no consumer redefines these types.

pub mod artifact;
pub mod capability;
pub mod identity;
pub mod ids;
pub mod protocol;
pub mod review;
pub mod session;
pub mod telemetry;

/// Programme-wide error type for contract-level validation failures.
#[derive(Debug, thiserror::Error)]
pub enum TapestryError {
    /// A required field was empty or absent.
    #[error("missing required field: {0}")]
    MissingField(&'static str),

    /// A value violated a structural invariant (bad id, bad digest, ...).
    #[error("invalid value for {field}: {reason}")]
    InvalidValue { field: &'static str, reason: String },

    /// A state transition or protocol step was attempted out of order.
    #[error("illegal transition: {0}")]
    IllegalTransition(String),

    /// Serialisation or deserialisation of a contract failed.
    #[error(transparent)]
    Serde(#[from] serde_json::Error),
}

/// Convenience alias used throughout the crate.
pub type Result<T> = std::result::Result<T, TapestryError>;

/// The TAP protocol version this crate speaks.
pub const TAP_VERSION: &str = "TAP/1";

//! Resumable chunk bookkeeping for artefact transfer (directive §9).
//!
//! Tracks which byte ranges of an artefact have been acknowledged so a
//! reconnect resumes rather than restarts, and a replayed frame cannot
//! create duplicate effects.

use std::collections::BTreeMap;

use serde::{Deserialize, Serialize};

use crate::ids::ArtifactId;
use crate::{Result, TapestryError};

/// Receiver-side resume state for one artefact.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct TransferState {
    pub artifact: ArtifactId,
    pub total_len: u64,
    pub chunk_len: u64,
    /// Offset → chunk digest, for every acknowledged chunk.
    pub acknowledged: BTreeMap<u64, String>,
}

impl TransferState {
    /// New transfer state; `total_len` must be chunkable by `chunk_len`.
    pub fn new(artifact: ArtifactId, total_len: u64, chunk_len: u64) -> Result<Self> {
        if chunk_len == 0 || chunk_len > crate::protocol::frame::MAX_CHUNK_LEN {
            return Err(TapestryError::InvalidValue {
                field: "chunk_len",
                reason: format!("must be 1..={}", crate::protocol::frame::MAX_CHUNK_LEN),
            });
        }
        if total_len == 0 {
            return Err(TapestryError::InvalidValue {
                field: "total_len",
                reason: "artefact must not be empty".into(),
            });
        }
        Ok(Self {
            artifact,
            total_len,
            chunk_len,
            acknowledged: BTreeMap::new(),
        })
    }

    /// Next unacknowledged offset, or `None` when complete.
    pub fn next_offset(&self) -> Option<u64> {
        let mut expected = 0u64;
        for &offset in self.acknowledged.keys() {
            if offset == expected {
                expected += self.chunk_len;
            } else {
                break;
            }
        }
        (expected < self.total_len).then_some(expected)
    }

    /// Acknowledge a chunk at `offset` with `digest`. Re-acknowledging the
    /// same offset with the same digest is a no-op (idempotent); a
    /// conflicting digest is an error.
    pub fn acknowledge(&mut self, offset: u64, digest: impl Into<String>) -> Result<bool> {
        if offset >= self.total_len || offset % self.chunk_len != 0 {
            return Err(TapestryError::InvalidValue {
                field: "offset",
                reason: format!(
                    "not a valid chunk boundary for len {total}",
                    total = self.total_len
                ),
            });
        }
        let digest = digest.into();
        match self.acknowledged.get(&offset) {
            Some(existing) if *existing == digest => Ok(false),
            Some(_) => Err(TapestryError::InvalidValue {
                field: "digest",
                reason: "conflicting digest for already-acknowledged chunk".into(),
            }),
            None => {
                self.acknowledged.insert(offset, digest);
                Ok(true)
            }
        }
    }

    /// Whether every byte of the artefact is acknowledged.
    pub fn is_complete(&self) -> bool {
        self.next_offset().is_none()
    }

    /// Bytes acknowledged so far (clamped to `total_len`).
    pub fn received_bytes(&self) -> u64 {
        let chunks = self.acknowledged.len() as u64;
        chunks.saturating_mul(self.chunk_len).min(self.total_len)
    }
}

/// Acknowledgement frame payload.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ChunkAck {
    pub artifact: ArtifactId,
    pub offset: u64,
    pub digest: String,
}

#[cfg(test)]
mod tests {
    use super::*;

    fn state() -> TransferState {
        TransferState::new(ArtifactId::generate(), 10 * (1 << 20), 1 << 20).unwrap()
    }

    #[test]
    fn chunk_bounds_enforced() {
        assert!(TransferState::new(ArtifactId::generate(), 100, 0).is_err());
        assert!(TransferState::new(ArtifactId::generate(), 100, (2 << 20) as u64).is_err());
        assert!(TransferState::new(ArtifactId::generate(), 0, 1024).is_err());
    }

    #[test]
    fn resume_walks_offsets_in_order() {
        let mut s = state();
        for i in 0..5u64 {
            assert_eq!(s.next_offset(), Some(i * s.chunk_len));
            s.acknowledge(i * s.chunk_len, format!("d{i}")).unwrap();
        }
        assert_eq!(s.received_bytes(), 5 * s.chunk_len);
        assert!(!s.is_complete());
    }

    #[test]
    fn complete_when_all_chunks_acknowledged() {
        let mut s = state();
        let chunks = s.total_len.div_ceil(s.chunk_len);
        for i in 0..chunks {
            s.acknowledge(i * s.chunk_len, "d").unwrap();
        }
        assert!(s.is_complete());
        assert_eq!(s.next_offset(), None);
        assert_eq!(s.received_bytes(), s.total_len);
    }

    #[test]
    fn duplicate_ack_is_noop_conflict_is_error() {
        let mut s = state();
        assert!(s.acknowledge(0, "digest-a").unwrap());
        assert!(!s.acknowledge(0, "digest-a").unwrap());
        assert!(s.acknowledge(0, "digest-b").is_err());
    }

    #[test]
    fn misaligned_and_out_of_range_offsets_rejected() {
        let mut s = state();
        assert!(s.acknowledge(512, "d").is_err());
        assert!(s.acknowledge(s.total_len, "d").is_err());
    }

    #[test]
    fn serde_roundtrip() {
        let mut s = state();
        s.acknowledge(0, "d").unwrap();
        let back: TransferState =
            serde_json::from_str(&serde_json::to_string(&s).unwrap()).unwrap();
        assert_eq!(s, back);
    }
}

//! TAP/1 frame schema.
//!
//! Every message on the wire is a frame: session-scoped, channel-tagged,
//! sequence-numbered, length-prefixed and digest-stamped. Frames are pure
//! data here; the byte encoding is the transport swarm's concern.

use serde::{Deserialize, Serialize};
use sha2::{Digest as _, Sha256};

use crate::ids::{ArtifactId, DeviceId, SessionId};
use crate::protocol::Channel;
use crate::{Result, TapestryError};

/// Maximum frame payload accepted by a conforming receiver (guards against
/// decompression/memory attacks, §28).
pub const MAX_FRAME_PAYLOAD: u64 = 64 << 20; // 64 MiB

/// Maximum chunk size for artefact transfer.
pub const MAX_CHUNK_LEN: u64 = 1 << 20; // 1 MiB

/// A TAP frame. `payload` is opaque at this layer.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Frame {
    /// Always `1` on the wire for TAP/1.
    pub schema_version: u32,
    pub session: SessionId,
    pub channel: Channel,
    /// Frame type within the channel, e.g. "chunk", "ack", "heartbeat".
    pub frame_type: String,
    /// Monotonic per-session, per-channel sequence. Idempotency key.
    pub seq: u64,
    /// Sender device identity.
    pub sender: DeviceId,
    /// Present for artefact/media/review frames.
    pub artifact: Option<ArtifactId>,
    /// Byte offset into the artefact, for chunked transfer.
    pub offset: Option<u64>,
    /// Payload length in bytes.
    pub len: u64,
    /// Hex SHA-256 of the payload.
    pub digest: String,
    pub payload: Vec<u8>,
}

impl Frame {
    /// Construct a frame carrying `payload`, computing `len` and `digest`.
    pub fn new(
        session: SessionId,
        channel: Channel,
        frame_type: impl Into<String>,
        seq: u64,
        sender: DeviceId,
        payload: Vec<u8>,
    ) -> Self {
        Self {
            schema_version: crate::protocol::PROTOCOL_VERSION,
            session,
            channel,
            frame_type: frame_type.into(),
            seq,
            sender,
            artifact: None,
            offset: None,
            len: payload.len() as u64,
            digest: hex::encode(Sha256::digest(&payload)),
            payload,
        }
    }

    /// Structural validation: schema version, size limits, digest match.
    pub fn validate(&self) -> Result<()> {
        if self.schema_version != crate::protocol::PROTOCOL_VERSION {
            return Err(TapestryError::InvalidValue {
                field: "schema_version",
                reason: format!("expected {}", crate::protocol::PROTOCOL_VERSION),
            });
        }
        if self.len > MAX_FRAME_PAYLOAD {
            return Err(TapestryError::InvalidValue {
                field: "len",
                reason: format!("exceeds MAX_FRAME_PAYLOAD ({MAX_FRAME_PAYLOAD})"),
            });
        }
        if self.len != self.payload.len() as u64 {
            return Err(TapestryError::InvalidValue {
                field: "len",
                reason: format!(
                    "declared {} but payload is {}",
                    self.len,
                    self.payload.len()
                ),
            });
        }
        if self.digest != hex::encode(Sha256::digest(&self.payload)) {
            return Err(TapestryError::InvalidValue {
                field: "digest",
                reason: "payload digest mismatch".into(),
            });
        }
        if let Some(offset) = self.offset {
            if self.frame_type != "chunk" {
                return Err(TapestryError::InvalidValue {
                    field: "offset",
                    reason: "only chunk frames carry an offset".into(),
                });
            }
            if self.len > MAX_CHUNK_LEN {
                return Err(TapestryError::InvalidValue {
                    field: "len",
                    reason: format!("chunk exceeds MAX_CHUNK_LEN ({MAX_CHUNK_LEN})"),
                });
            }
            let _ = offset;
        }
        Ok(())
    }

    /// Serialise to JSON and back, byte-for-byte stable.
    pub fn to_json(&self) -> Result<Vec<u8>> {
        Ok(serde_json::to_vec(self)?)
    }

    pub fn from_json(bytes: &[u8]) -> Result<Self> {
        Ok(serde_json::from_slice(bytes)?)
    }
}

