//! Scoped device credentials (Gate 2, directive §11).
//!
//! DreamSequence-shaped: the traits are the contract; the POC provider
//! reads token material from files. TV clients receive only scoped
//! credentials — never vault or provider keys.

use std::path::{Path, PathBuf};
use std::time::{SystemTime, UNIX_EPOCH};

use serde::{Deserialize, Serialize};
use sha2::{Digest as _, Sha256};

/// Actions a device may or may not perform.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Scope {
    /// Denied-by-default set (§11): never granted to a television.
    ReceiveSession,
    ReceiveArtefact,
    ReadTelemetry,
    SubmitReview,
    RequestRegeneration,
    ReadVault,
    ProviderApi,
    ShellExecute,
    RepositoryRead,
    DeploymentAuthorize,
}

impl Scope {
    /// Scopes a presentation device legitimately holds.
    pub fn device_scopes() -> &'static [Scope] {
        &[
            Scope::ReceiveSession,
            Scope::ReceiveArtefact,
            Scope::ReadTelemetry,
            Scope::SubmitReview,
            Scope::RequestRegeneration,
        ]
    }

    pub fn is_denied_by_default(self) -> bool {
        matches!(
            self,
            Scope::ReadVault
                | Scope::ProviderApi
                | Scope::ShellExecute
                | Scope::RepositoryRead
                | Scope::DeploymentAuthorize
        )
    }

    fn token_file_name(self) -> &'static str {
        match self {
            Scope::ReceiveSession => "receive_session",
            Scope::ReceiveArtefact => "receive_artefact",
            Scope::ReadTelemetry => "read_telemetry",
            Scope::SubmitReview => "submit_review",
            Scope::RequestRegeneration => "request_regeneration",
            Scope::ReadVault => "read_vault",
            Scope::ProviderApi => "provider_api",
            Scope::ShellExecute => "shell_execute",
            Scope::RepositoryRead => "repository_read",
            Scope::DeploymentAuthorize => "deployment_authorize",
        }
    }
}

/// A device credential with explicit scopes and expiry.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ScopedCredential {
    pub device_id: tapestry_core::ids::DeviceId,
    pub scopes: Vec<Scope>,
    pub issued_at_unix: u64,
    pub expires_at_unix: u64,
    /// Digest of the token material — proofs of possession, never the token.
    pub token_digest: String,
}

#[derive(Debug, thiserror::Error)]
pub enum AuthError {
    #[error("scope {0:?} is denied by default and cannot be granted to a device")]
    DeniedByDefault(Scope),
    #[error("credential for scope {0:?} not found in vault")]
    NotFound(Scope),
    #[error("credential expired at {0}")]
    Expired(u64),
    #[error("vault read failed: {0}")]
    VaultRead(String),
}

/// Who a device is.
pub trait IdentityProvider {
    fn identity(&self) -> tapestry_core::identity::DeviceIdentity;
}

/// Where scoped credentials come from.
pub trait CredentialProvider {
    fn credential(&self, scope: Scope, now_unix: u64) -> Result<String, AuthError>;
}

/// Who may do what.
pub trait SessionAuthorizer {
    fn authorize(&self, credential: &ScopedCredential, scope: Scope, now_unix: u64) -> bool;
}

/// POC provider: token material lives as files under a data dir
/// (`<data_dir>/<scope>.token`), standing in for DreamSequence vaults.
/// No network; no provider keys ever cross this interface.
#[derive(Debug, Clone)]
pub struct DreamSequenceVaultProvider {
    pub data_dir: PathBuf,
}

impl DreamSequenceVaultProvider {
    pub fn issue_scoped_credential(
        &self,
        device_id: tapestry_core::ids::DeviceId,
        now_unix: u64,
        validity_secs: u64,
    ) -> Result<ScopedCredential, AuthError> {
        let mut token_digest = Sha256::new();
        let mut scopes = Vec::new();
        for scope in Scope::device_scopes() {
            let token = self.credential(*scope, now_unix)?;
            token_digest.update(token.as_bytes());
            token_digest.update(b"\n");
            scopes.push(*scope);
        }
        Ok(ScopedCredential {
            device_id,
            scopes,
            issued_at_unix: now_unix,
            expires_at_unix: now_unix + validity_secs,
            token_digest: hex::encode(token_digest.finalize()),
        })
    }
}

impl CredentialProvider for DreamSequenceVaultProvider {
    fn credential(&self, scope: Scope, _now_unix: u64) -> Result<String, AuthError> {
        if scope.is_denied_by_default() {
            // The vault refuses to hand these to any device, ever.
            return Err(AuthError::DeniedByDefault(scope));
        }
        let path = self
            .data_dir
            .join(format!("{}.token", scope.token_file_name()));
        std::fs::read_to_string(&path)
            .map(|s| s.trim().to_owned())
            .map_err(|_| AuthError::NotFound(scope))
    }
}

/// Authorizer: scope present, not expired, not denied-by-default.
#[derive(Debug, Clone, Copy, Default)]
pub struct ScopedAuthorizer;

impl SessionAuthorizer for ScopedAuthorizer {
    fn authorize(&self, credential: &ScopedCredential, scope: Scope, now_unix: u64) -> bool {
        if scope.is_denied_by_default() {
            return false;
        }
        credential.scopes.contains(&scope) && now_unix < credential.expires_at_unix
    }
}

pub fn now_unix() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0)
}

/// Write the POC vault token files for a device under `data_dir`.
/// Tokens are random-ish but deterministic per (device, scope) — enough for
/// a POC; real entropy belongs to DreamSequence.
pub fn seed_vault(
    data_dir: &Path,
    device_id: &tapestry_core::ids::DeviceId,
) -> std::io::Result<()> {
    std::fs::create_dir_all(data_dir)?;
    for scope in Scope::device_scopes() {
        let material = format!("poc-token:{}:{}", device_id, scope.token_file_name());
        let digest = hex::encode(Sha256::digest(material.as_bytes()));
        std::fs::write(
            data_dir.join(format!("{}.token", scope.token_file_name())),
            digest,
        )?;
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn vault() -> (tempfile::TempDir, tapestry_core::ids::DeviceId) {
        let dir = tempfile::tempdir().unwrap();
        let device = tapestry_core::ids::DeviceId::generate();
        seed_vault(dir.path(), &device).unwrap();
        (dir, device)
    }

    #[test]
    fn device_scopes_exclude_denied_defaults() {
        for scope in Scope::device_scopes() {
            assert!(!scope.is_denied_by_default());
        }
        assert!(Scope::ProviderApi.is_denied_by_default());
        assert!(Scope::ShellExecute.is_denied_by_default());
    }

    #[test]
    fn vault_issues_credential_with_device_scopes() {
        let (dir, device) = vault();
        let provider = DreamSequenceVaultProvider {
            data_dir: dir.path().into(),
        };
        let cred = provider
            .issue_scoped_credential(device, 1_000, 3_600)
            .unwrap();
        assert_eq!(cred.scopes.len(), Scope::device_scopes().len());
        assert_eq!(cred.expires_at_unix, 4_600);
        assert_eq!(cred.token_digest.len(), 64);
    }

    #[test]
    fn authorizer_grants_then_expires() {
        let (dir, device) = vault();
        let provider = DreamSequenceVaultProvider {
            data_dir: dir.path().into(),
        };
        let cred = provider
            .issue_scoped_credential(device, 1_000, 100)
            .unwrap();
        let auth = ScopedAuthorizer;
        assert!(auth.authorize(&cred, Scope::SubmitReview, 1_050));
        assert!(!auth.authorize(&cred, Scope::SubmitReview, 1_200)); // expired
        assert!(!auth.authorize(&cred, Scope::ReadVault, 1_050)); // denied by default
        assert!(!auth.authorize(&cred, Scope::ProviderApi, 1_050));
    }

    #[test]
    fn vault_refuses_denied_scopes_even_if_file_existed() {
        let dir = tempfile::tempdir().unwrap();
        let provider = DreamSequenceVaultProvider {
            data_dir: dir.path().into(),
        };
        let err = provider.credential(Scope::ReadVault, 0).unwrap_err();
        assert!(matches!(err, AuthError::DeniedByDefault(Scope::ReadVault)));
    }

    #[test]
    fn missing_token_file_is_not_found() {
        let dir = tempfile::tempdir().unwrap();
        let provider = DreamSequenceVaultProvider {
            data_dir: dir.path().into(),
        };
        let err = provider.credential(Scope::SubmitReview, 0).unwrap_err();
        assert!(matches!(err, AuthError::NotFound(_)));
    }

    #[test]
    fn credential_serde_roundtrip() {
        let (dir, device) = vault();
        let provider = DreamSequenceVaultProvider {
            data_dir: dir.path().into(),
        };
        let cred = provider.issue_scoped_credential(device, 0, 60).unwrap();
        let back: ScopedCredential =
            serde_json::from_str(&serde_json::to_string(&cred).unwrap()).unwrap();
        assert_eq!(cred, back);
    }
}

//! The `tapestry` command surface (directive §22). Exit codes are stable.

use std::path::PathBuf;

use clap::{Parser, Subcommand};

/// Stable exit codes: agents depend on these, never on terminal scraping.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(i32)]
pub enum ExitCode {
    Ok = 0,
    Usage = 2,
    Auth = 3,
    NoDevice = 4,
    ReviewRejected = 5,
    Timeout = 6,
}

#[derive(Parser, Debug)]
#[command(
    name = "tapestry",
    version,
    about = "Tapestry — distributed presentation and human-inspection harness"
)]
pub struct Cli {
    /// Machine-readable request file instead of a prompt (with --machine).
    /// If a subcommand is also given, the subcommand wins.
    #[arg(long, value_name = "FILE")]
    pub request: Option<PathBuf>,

    /// Print only machine-readable JSON output.
    #[arg(long, requires = "request")]
    pub machine: bool,

    /// Bare positional prompt: `tapestry "prompt"` (§22 primary interaction).
    #[arg(value_name = "PROMPT", conflicts_with_all = ["request", "machine"])]
    pub prompt_text: Option<String>,

    #[command(subcommand)]
    pub command: Option<Command>,
}

#[derive(Subcommand, Debug)]
pub enum Command {
    /// Run a prompt through the full drive: inference → artefact → review.
    Prompt {
        /// The prompt text (quoted).
        text: String,
    },
    /// Stage a local file as an artefact.
    Send {
        #[arg(value_name = "FILE")]
        file: PathBuf,
    },
    /// Present a single artefact for review.
    Show {
        #[arg(value_name = "ARTIFACT")]
        artifact: String,
    },
    /// Present artefacts side by side for comparison.
    Compare {
        #[arg(value_name = "A")]
        a: String,
        #[arg(value_name = "B")]
        b: String,
    },
    /// Show the current presentation target.
    Target,
    /// List discovered devices.
    Devices,
    /// Tactical snapshot of the current drive.
    Status,
    /// List sessions known to this coordinator.
    Sessions,
    /// Unified storage visibility (§16).
    Storage,
    /// Create an ephemeral share link for the latest artefact.
    Share,
    /// Diagnostics: credentials, transport, knowledge journal, resources.
    Doctor,
}

impl ExitCode {
    pub fn as_i32(self) -> i32 {
        self as i32
    }
}

/// Dispatch a parsed CLI. Returns the process exit code.
pub fn run(cli: &Cli) -> i32 {
    if let Some(text) = &cli.prompt_text {
        return crate::slice::run_prompt(text, cli.machine);
    }
    match &cli.command {
        Some(Command::Prompt { text }) => crate::slice::run_prompt(text, cli.machine),
        Some(Command::Send { file }) => crate::slice::send_file(file, cli.machine),
        Some(Command::Show { artifact }) => crate::slice::show(artifact),
        Some(Command::Compare { a, b }) => crate::slice::compare(a, b),
        Some(Command::Target) => crate::slice::target(),
        Some(Command::Devices) => crate::slice::devices(),
        Some(Command::Status) => crate::slice::status(),
        Some(Command::Sessions) => crate::slice::sessions(),
        Some(Command::Storage) => crate::slice::storage(),
        Some(Command::Share) => crate::slice::share(),
        Some(Command::Doctor) => crate::slice::doctor(),
        None if cli.request.is_some() => {
            crate::slice::machine_request(cli.request.as_ref().expect("checked above"))
        }
        None => {
            eprintln!("usage: tapestry \"prompt\" | tapestry <command> | tapestry --request f.json --machine");
            ExitCode::Usage.as_i32()
        }
    }
}

//! Padagonia-shaped durable knowledge journal (Gate 5, directive §26/§27).
//!
//! Append-only, digest-chained JSONL: provenance and confidence are
//! preserved and never collapsed into one truth category. Not a consensus
//! database.

use std::io::{BufRead, Write};
use std::path::{Path, PathBuf};

use serde::{Deserialize, Serialize};
use sha2::{Digest as _, Sha256};

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum NodeKind {
    Device,
    User,
    Agent,
    Session,
    Prompt,
    Task,
    Artefact,
    Revision,
    Model,
    Provider,
    Review,
    Decision,
    Annotation,
    Capability,
    StorageVolume,
    Transfer,
    Render,
    Update,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "SCREAMING_SNAKE_CASE")]
pub enum Relationship {
    GeneratedBy,
    DerivedFrom,
    DisplayedOn,
    RequestedBy,
    ReviewedBy,
    SelectedOver,
    RejectedFor,
    SentTo,
    ReceivedFrom,
    HostedBy,
    ConnectedVia,
    Supersedes,
    BelongsToSession,
    HasCapability,
}

/// Where a piece of knowledge came from. These categories MUST NOT merge.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Origin {
    ExplicitHumanJudgement,
    AgentJudgement,
    InferredPreference,
    HistoricalCorrelation,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct KnowledgeNode {
    pub id: String,
    pub kind: NodeKind,
    pub label: String,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct KnowledgeEdge {
    pub from: String,
    pub rel: Relationship,
    pub to: String,
    /// 0.0..1.0 — confidence is per-edge, per-origin.
    pub confidence: f32,
    pub origin: Origin,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
enum JournalEvent {
    Node(KnowledgeNode),
    Edge(KnowledgeEdge),
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct JournalRecord {
    seq: u64,
    /// sha256(prev_digest || payload).
    digest: String,
    event: JournalEvent,
}

#[derive(Debug, thiserror::Error)]
pub enum JournalError {
    #[error("torn or tampered journal at seq {0}")]
    Integrity(u64),
    #[error("io error: {0}")]
    Io(#[from] std::io::Error),
    #[error("serde error: {0}")]
    Serde(#[from] serde_json::Error),
}

/// File-backed knowledge journal.
#[derive(Debug, Clone)]
pub struct KnowledgeJournal {
    path: PathBuf,
    seq: u64,
    head_digest: String,
    nodes: Vec<KnowledgeNode>,
    edges: Vec<KnowledgeEdge>,
}

fn genesis_digest() -> String {
    hex::encode(Sha256::digest(b"tapestry-genesis"))
}

impl KnowledgeJournal {
    /// Open (or create) a journal, replaying and verifying the chain.
    /// Truncates at the first torn/tampered record — what survives is
    /// exactly what provably happened.
    pub fn open(path: &Path) -> Result<Self, JournalError> {
        let mut journal = Self {
            path: path.to_owned(),
            seq: 0,
            head_digest: genesis_digest(),
            nodes: Vec::new(),
            edges: Vec::new(),
        };
        if path.exists() {
            journal.replay()?;
            journal.persist_verified_prefix()?;
        }
        Ok(journal)
    }

    fn replay(&mut self) -> Result<(), JournalError> {
        let file = std::fs::File::open(&self.path)?;
        for line in std::io::BufReader::new(file).lines() {
            let line = line?;
            if line.trim().is_empty() {
                continue;
            }
            let record: JournalRecord = match serde_json::from_str(&line) {
                Ok(r) => r,
                Err(_) => break, // torn tail write
            };
            if record.seq != self.seq + 1 {
                break;
            }
            if !verify_chain(&self.head_digest, &record) {
                break;
            }
            self.seq = record.seq;
            self.head_digest = record.digest.clone();
            match &record.event {
                JournalEvent::Node(n) => self.nodes.push(n.clone()),
                JournalEvent::Edge(e) => self.edges.push(e.clone()),
            }
        }
        Ok(())
    }

    /// Rewrite the file with only the verified prefix (atomic via tmp+rename).
    fn persist_verified_prefix(&self) -> Result<(), JournalError> {
        // The original payloads must be preserved byte-exact, so filter lines.
        let file = std::fs::File::open(&self.path)?;
        let mut verified = String::new();
        let mut seq = 0u64;
        let mut head = genesis_digest();
        for line in std::io::BufReader::new(file).lines() {
            let line = line?;
            if line.trim().is_empty() {
                continue;
            }
            let record: JournalRecord = match serde_json::from_str(&line) {
                Ok(r) => r,
                Err(_) => break,
            };
            if record.seq != seq + 1 || !verify_chain(&head, &record) {
                break;
            }
            seq = record.seq;
            head = record.digest.clone();
            verified.push_str(&line);
            verified.push('\n');
        }
        let tmp = self.path.with_extension("tmp");
        std::fs::write(&tmp, verified)?;
        std::fs::rename(&tmp, &self.path)?;
        Ok(())
    }

    fn append_record(&mut self, event: JournalEvent) -> Result<(), JournalError> {
        let payload = serde_json::to_vec(&event)?;
        let mut hasher = Sha256::new();
        hasher.update(self.head_digest.as_bytes());
        hasher.update(&payload);
        let digest = hex::encode(hasher.finalize());
        let record = JournalRecord {
            seq: self.seq + 1,
            digest: digest.clone(),
            event,
        };
        let mut file = std::fs::OpenOptions::new()
            .create(true)
            .append(true)
            .open(&self.path)?;
        writeln!(file, "{}", serde_json::to_string(&record)?)?;
        file.flush()?;
        self.seq += 1;
        self.head_digest = digest;
        // Keep the in-memory view consistent with what we just persisted.
        match record.event {
            JournalEvent::Node(n) => self.nodes.push(n),
            JournalEvent::Edge(e) => self.edges.push(e),
        }
        Ok(())
    }

    pub fn append_node(&mut self, node: KnowledgeNode) -> Result<(), JournalError> {
        self.append_record(JournalEvent::Node(node))
    }

    /// Append an edge; both endpoints must exist so the graph never
    /// references nothing.
    pub fn append_edge(&mut self, edge: KnowledgeEdge) -> Result<(), JournalError> {
        if !self.has_node(&edge.from) || !self.has_node(&edge.to) {
            return Err(JournalError::Integrity(self.seq));
        }
        self.append_record(JournalEvent::Edge(edge))
    }

    fn has_node(&self, id: &str) -> bool {
        self.nodes.iter().any(|n| n.id == id)
    }

    /// Edges where a human explicitly judged (SELECTED_OVER etc.).
    pub fn human_edges(&self) -> impl Iterator<Item = &KnowledgeEdge> {
        self.edges
            .iter()
            .filter(|e| e.origin == Origin::ExplicitHumanJudgement)
    }

    pub fn nodes(&self) -> &[KnowledgeNode] {
        &self.nodes
    }

    pub fn edges(&self) -> &[KnowledgeEdge] {
        &self.edges
    }
}

fn verify_chain(prev_digest: &str, record: &JournalRecord) -> bool {
    let payload = match serde_json::to_vec(&record.event) {
        Ok(p) => p,
        Err(_) => return false,
    };
    let mut hasher = Sha256::new();
    hasher.update(prev_digest.as_bytes());
    hasher.update(&payload);
    hex::encode(hasher.finalize()) == record.digest
}

#[cfg(test)]
mod tests {
