//! Mesut-shaped local task classification and lanes (Gate 4, directive §8).
//!
//! Playbook issues work; Mesut classifies and lanes it. Struct only —
//! no threads, so the POC scheduler is deterministic and testable.

use std::collections::VecDeque;

use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum WorkloadClass {
    Io,
    Compute,
    Blocking,
    Async,
    Critical,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Priority {
    Low,
    Normal,
    High,
    Critical,
}

/// Backpressure bound: one heavy media task must not starve navigation.
const MAX_LANE_LEN: usize = 64;

#[derive(Debug, thiserror::Error)]
pub enum SchedulerError {
    #[error("lane full for priority {0:?}: backpressure engaged")]
    LaneFull(Priority),
}

/// A unit of local work.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct TaskSpec {
    pub name: String,
    pub class: WorkloadClass,
    pub priority: Priority,
    pub estimated_ms: u64,
}

/// Classify by task name and optional size hint (bytes).
pub fn classify(task_name: &str, size_hint: Option<u64>) -> (WorkloadClass, Priority) {
    let name = task_name.to_ascii_lowercase();
    let heavy = size_hint.unwrap_or(0) > 16 << 20; // 16 MiB
    match name.split_whitespace().next().unwrap_or(&name) {
        n if n.contains("hash")
            || n.contains("thumbnail")
            || n.contains("qr")
            || n.contains("transcode") =>
        {
            let class = WorkloadClass::Compute;
            let priority = if heavy { Priority::Low } else { Priority::High };
            (class, priority)
        }
        n if n.contains("read") || n.contains("probe") || n.contains("metadata") => {
            (WorkloadClass::Blocking, Priority::High)
        }
        n if n.contains("upload")
            || n.contains("download")
            || n.contains("transfer")
            || n.contains("network") =>
        {
            (WorkloadClass::Async, Priority::Normal)
        }
        n if n.contains("remote")
            || n.contains("review")
            || n.contains("cancel")
            || n.contains("auth") =>
        {
            (WorkloadClass::Critical, Priority::Critical)
        }
        _ if heavy => (WorkloadClass::Compute, Priority::Low),
        _ => (WorkloadClass::Io, Priority::Normal),
    }
}

impl TaskSpec {
    pub fn from_name(task_name: &str, size_hint: Option<u64>) -> Self {
        let (class, priority) = classify(task_name, size_hint);
        Self {
            name: task_name.to_owned(),
            class,
            priority,
            estimated_ms: 0,
        }
    }
}

/// Priority lanes with backpressure and drain-by-session cancellation.
#[derive(Debug, Default)]
pub struct Lanes {
    lanes: [VecDeque<TaskSpec>; 4],
}

impl Lanes {
    pub fn new() -> Self {
        Self::default()
    }

    fn index(p: Priority) -> usize {
        match p {
            Priority::Critical => 3,
            Priority::High => 2,
            Priority::Normal => 1,
            Priority::Low => 0,
        }
    }

    /// Enqueue with backpressure: non-critical lanes reject when full.
    pub fn push(&mut self, task: TaskSpec) -> Result<(), SchedulerError> {
        let idx = Self::index(task.priority);
        if self.lanes[idx].len() >= MAX_LANE_LEN && task.priority != Priority::Critical {
            return Err(SchedulerError::LaneFull(task.priority));
        }
        self.lanes[idx].push_back(task);
        Ok(())
    }

    /// Pop the most urgent task: Critical first, Low last.
    pub fn pop_next(&mut self) -> Option<TaskSpec> {
        (0..4).rev().find_map(|i| self.lanes[i].pop_front())
    }

    /// Drain queued work for an abandoned session (structured cancellation).
    pub fn drain_cancelled(&mut self, session_hint: &str) -> usize {
        let mut drained = 0;
        for lane in self.lanes.iter_mut() {
            let before = lane.len();
            lane.retain(|t| !t.name.contains(session_hint));
            drained += before - lane.len();
        }
        drained
    }

    pub fn len(&self) -> usize {
        self.lanes.iter().map(VecDeque::len).sum()
    }

    pub fn is_empty(&self) -> bool {
        self.len() == 0
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn classification_rules() {
        assert_eq!(
            classify("hash artefact bytes", None),
            (WorkloadClass::Compute, Priority::High)
        );
        assert_eq!(
            classify("probe metadata", None),
            (WorkloadClass::Blocking, Priority::High)
        );
        assert_eq!(
            classify("transfer chunks", None),
            (WorkloadClass::Async, Priority::Normal)
        );
        assert_eq!(
            classify("review submission", None),
            (WorkloadClass::Critical, Priority::Critical)
        );
    }

    #[test]
    fn heavy_compute_downgrades_to_low() {
        assert_eq!(
            classify("transcode", Some(64 << 20)),
            (WorkloadClass::Compute, Priority::Low)
        );
    }

    #[test]
    fn critical_pops_first() {
        let mut lanes = Lanes::new();
        lanes
            .push(TaskSpec::from_name("thumbnail generation", None))
            .unwrap();
        lanes
            .push(TaskSpec::from_name("cancel session", None))
            .unwrap();
        let next = lanes.pop_next().unwrap();
        assert_eq!(next.priority, Priority::Critical);
        assert_eq!(lanes.len(), 1);
    }

    #[test]
    fn backpressure_rejects_full_lanes_but_not_critical() {
        let mut lanes = Lanes::new();
        for i in 0..MAX_LANE_LEN {
            lanes
                .push(TaskSpec {
                    name: format!("normal {i}"),
                    class: WorkloadClass::Io,
                    priority: Priority::Normal,
                    estimated_ms: 1,
                })
                .unwrap();
        }
        let err = lanes
            .push(TaskSpec::from_name("normal overflow", None))
            .unwrap_err();
        assert!(matches!(err, SchedulerError::LaneFull(Priority::Normal)));
        // Critical admission is never refused.
        lanes.push(TaskSpec::from_name("auth", None)).unwrap();
        assert_eq!(lanes.pop_next().unwrap().priority, Priority::Critical);
    }

    #[test]
    fn drain_cancelled_removes_only_matching_session() {
        let mut lanes = Lanes::new();
        lanes
            .push(TaskSpec {
                name: "tap-01 thumbnail".into(),
                class: WorkloadClass::Compute,
                priority: Priority::High,
                estimated_ms: 5,
            })
            .unwrap();
        lanes
            .push(TaskSpec {
                name: "tap-02 transfer".into(),
                class: WorkloadClass::Async,
                priority: Priority::Normal,
                estimated_ms: 5,
            })
            .unwrap();
        assert_eq!(lanes.drain_cancelled("tap-01"), 1);
        assert_eq!(lanes.len(), 1);
    }

    #[test]
    fn empty_lanes_report_empty() {
        assert!(Lanes::new().is_empty());
    }
}

//! Playbook adapter (Gate 3, directive §7).
//!
//! Runs a playbook drive as a subprocess, parses its JSONL journal into
//! gates, and supports cancellation. Playbook decides *what* should happen;
//! this adapter only observes and reports.

use std::io::{BufRead, BufReader};
use std::path::{Path, PathBuf};
use std::process::{Child, Command, Stdio};
use std::time::{Duration, Instant};

use serde::{Deserialize, Serialize};

/// Playbook-visible gates mapped from journal events.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "SCREAMING_SNAKE_CASE")]
pub enum DriveGate {
    RequestAccepted,
    PlanReady,
    GenerationStarted,
    ArtefactAvailable,
    ArtefactValidated,
    DisplayReady,
    HumanReviewRequired,
    HumanDecisionReceived,
    TaskComplete,
}

/// One journal line of a playbook drive.
#[derive(Debug, Clone, Deserialize)]
pub struct JournalLine {
    pub seq: u64,
    #[serde(default)]
    pub digest: String,
    pub event: serde_json::Value,
}

#[derive(Debug, thiserror::Error)]
pub enum DriveError {
    #[error("playbook binary failed: {0}")]
    Spawn(String),
    #[error("drive timed out after {0:?}")]
    Timeout(Duration),
    #[error("io error: {0}")]
    Io(#[from] std::io::Error),
}

/// Handle to a running drive; dropping after `kill_on_cancellation` aborts.
pub struct Drive {
    journal_path: PathBuf,
    child: Option<Child>,
}

impl Drive {
    /// Start `playbook mvp --journal <path>`, optionally blocking until the
    /// drive completes (or the timeout elapses).
    pub fn start(journal_path: &Path, timeout: Option<Duration>) -> Result<Self, DriveError> {
        let child = Command::new("playbook")
            .arg("mvp")
            .arg("--journal")
            .arg(journal_path)
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .spawn()
            .map_err(|e| DriveError::Spawn(e.to_string()))?;
        let mut drive = Drive {
            journal_path: journal_path.to_owned(),
            child: Some(child),
        };
        if let Some(t) = timeout {
            let started = Instant::now();
            while !drive.is_finished() {
                if started.elapsed() > t {
                    return Err(DriveError::Timeout(t));
                }
                std::thread::sleep(Duration::from_millis(20));
            }
            drive.wait()?;
        }
        Ok(drive)
    }

    /// Non-blocking liveness probe: reaps the child on exit so no zombie
    /// lingers (a zombie still owns a /proc entry).
    pub fn is_finished(&mut self) -> bool {
        match self.child.as_mut() {
            Some(c) => match c.try_wait() {
                Ok(Some(_)) => true,
                Ok(None) => false,
                Err(_) => true,
            },
            None => true,
        }
    }

    /// Cancel the drive by killing the child process.
    pub fn cancel(&mut self) -> Result<(), DriveError> {
        if let Some(child) = self.child.as_mut() {
            child.kill()?;
            child.wait()?;
            self.child = None;
        }
        Ok(())
    }

    /// Reap the child, returning its exit status.
    pub fn wait(&mut self) -> Result<Option<std::process::ExitStatus>, DriveError> {
        if let Some(child) = self.child.as_mut() {
            let status = child.wait()?;
            self.child = None;
            Ok(Some(status))
        } else {
            Ok(None)
        }
    }

    /// Read and parse the journal produced so far.
    pub fn journal(&self) -> Result<Vec<JournalLine>, DriveError> {
        let mut lines = Vec::new();
        if !self.journal_path.exists() {
            return Ok(lines);
        }
        let file = std::fs::File::open(&self.journal_path)?;
        for line in BufReader::new(file).lines() {
            let line = line?;
            if line.trim().is_empty() {
                continue;
            }
            match serde_json::from_str::<JournalLine>(&line) {
                Ok(l) => lines.push(l),
                Err(_) => break, // torn tail
            }
        }
        Ok(lines)
    }

    /// Map journal events onto DriveGates in order.
    pub fn gates(journal: &[JournalLine]) -> Vec<DriveGate> {
        let mut gates = Vec::new();
        for line in journal {
            let etype = line
                .event
                .get("type")
                .and_then(|v| v.as_str())
                .unwrap_or("");
            match etype {
                "drive_started" => {
                    gates.push(DriveGate::RequestAccepted);
                    gates.push(DriveGate::PlanReady);
                    gates.push(DriveGate::GenerationStarted);
                }
                "down_changed" => gates.push(DriveGate::ArtefactAvailable),
                _ => {}
            }
        }
        if !journal.is_empty() {
            gates.push(DriveGate::HumanReviewRequired);
            gates.push(DriveGate::TaskComplete);
        }
        gates
    }
}

impl Drop for Drive {
    fn drop(&mut self) {
        // Never leave an orphaned playbook behind.
        let _ = self.cancel();
    }
}

