pub fn doctor() -> i32 {
    let dirs = DataDirs::resolve();
    let mut checks = Vec::new();

    checks.push(CheckResult::new(
        "vault",
        dirs.vault().exists()
            && std::fs::read_dir(dirs.vault())
                .map(|d| d.flatten().count())
                .unwrap_or(0)
                > 0,
        format!(
            "{} token file(s)",
            std::fs::read_dir(dirs.vault())
                .map(|d| d.flatten().count())
                .unwrap_or(0)
        ),
    ));
    checks.push(CheckResult::new(
        "transport",
        dirs.transport().exists(),
        format!("loopback root: {}", dirs.transport().display()),
    ));
    checks.push(CheckResult::new(
        "knowledge",
        dirs.knowledge().join("tapestry.jsonl").exists(),
        format!(
            "journal: {}",
            dirs.knowledge().join("tapestry.jsonl").display()
        ),
    ));
    checks.push(CheckResult::new(
        "playbook",
        std::process::Command::new("playbook")
            .arg("policy")
            .output()
            .map(|o| o.status.success())
            .unwrap_or(false),
        "playbook binary reachable".to_string(),
    ));
    match PressureSignals::read() {
        Some(p) => checks.push(CheckResult::new(
            "pressure",
            true,
            format!(
                "mem available: {} MiB, load: {:.2}",
                p.mem_available_bytes >> 20,
                p.load_1m
            ),
        )),
        None => checks.push(CheckResult::new(
            "pressure",
            true,
            "/proc unavailable — advisory skipped",
        )),
    }

    let all_ok = checks.iter().all(|c| c.ok);
    for c in &checks {
        println!(
            "{:4}  {:10}  {}",
            if c.ok { "✓" } else { "✗" },
            c.name,
            c.detail
        );
    }
    if all_ok {
        ExitCode::Ok.as_i32()
    } else {
        ExitCode::Usage.as_i32()
    }
}

pub fn machine_request(request: &Path) -> i32 {
    match std::fs::read_to_string(request) {
        Ok(body) => match serde_json::from_str::<serde_json::Value>(&body) {
            Ok(req) => {
                let prompt = req
                    .get("prompt")
                    .and_then(|p| p.as_str())
                    .unwrap_or_default();
                if prompt.is_empty() {
                    eprintln!("tapestry: request file needs a \"prompt\" field");
                    return ExitCode::Usage.as_i32();
                }
                run_prompt(prompt, true)
            }
            Err(e) => {
                eprintln!("tapestry: request file is not valid JSON: {e}");
                ExitCode::Usage.as_i32()
            }
        },
        Err(e) => {
            eprintln!("tapestry: cannot read {request:?}: {e}");
            ExitCode::Usage.as_i32()
        }
    }
}

//! TempCheq-derived temperature policy (Gate 3, directive §12).
//!
//! TempCheq provides heuristic priors, not measured truth. Runtime consumes
//! the prior, may adjust within the band, and logs every adjustment.

use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Band {
    Low,
    Moderate,
    High,
}

impl Band {
    pub fn contains(self, t: f32) -> bool {
        let (lo, hi) = self.range();
        t >= lo && t <= hi
    }

    /// (inclusive_low, inclusive_high)
    pub fn range(self) -> (f32, f32) {
        match self {
            Band::Low => (0.0, 0.3),
            Band::Moderate => (0.4, 0.7),
            Band::High => (0.8, 1.0),
        }
    }

    fn clamp_value(self, t: f32) -> f32 {
        let (lo, hi) = self.range();
        t.clamp(lo, hi)
    }
}

/// One versioned policy entry: a prior with provenance.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct PolicyEntry {
    pub task_class: String,
    pub band: Band,
    pub recommended_initial: f32,
    /// 0.0..1.0 — heuristics are not measured truth, so confidence matters.
    pub confidence: f32,
    pub evidence_origin: String,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct PolicyTable {
    pub version: u32,
    pub entries: Vec<PolicyEntry>,
}

#[derive(Debug, thiserror::Error)]
pub enum PolicyError {
    #[error("no policy prior for task class {0:?}")]
    NoPrior(String),
}

/// Every adjustment is a first-class loggable record (§12).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Adjustment {
    pub task_class: String,
    pub original: f32,
    pub selected: f32,
    pub band: Band,
    pub reason: String,
}

impl std::fmt::Display for Adjustment {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(
            f,
            "temp[{}]: {} -> {} (band {:?}, reason: {})",
            self.task_class, self.original, self.selected, self.band, self.reason
        )
    }
}

/// The heuristic prior table (versioned; empirics supersede it later).
pub fn default_table() -> PolicyTable {
    let entry = |task_class: &str, band: Band, rec: f32| PolicyEntry {
        task_class: task_class.into(),
        band,
        recommended_initial: rec,
        confidence: 0.6,
        evidence_origin: "tempcheq-heuristic".into(),
    };
    PolicyTable {
        version: 1,
        entries: vec![
            entry("deterministic_extraction", Band::Low, 0.2),
            entry("classification", Band::Low, 0.2),
            entry("visual_critique", Band::Moderate, 0.6),
            entry("concept_generation", Band::High, 0.9),
            entry("evaluation", Band::Low, 0.3),
        ],
    }
}

impl PolicyTable {
    pub fn prior_for(&self, task_class: &str) -> Option<&PolicyEntry> {
        self.entries.iter().find(|e| e.task_class == task_class)
    }

    /// Apply a requested temperature within the policy band, clamping and
    /// recording the adjustment. Out-of-band requests are clamped, never
    /// refused — but the clamp is always logged.
    pub fn adjust(
        &self,
        task_class: &str,
        requested: f32,
        reason: &str,
    ) -> Result<Adjustment, PolicyError> {
        let prior = self
            .prior_for(task_class)
            .ok_or_else(|| PolicyError::NoPrior(task_class.to_owned()))?;
        let selected = prior.band.clamp_value(requested);
        Ok(Adjustment {
            task_class: task_class.to_owned(),
            original: requested,
            selected,
            band: prior.band,
            reason: reason.to_owned(),
        })
    }

    /// Initial temperature for a class from the prior.
    pub fn initial(&self, task_class: &str) -> Result<f32, PolicyError> {
        self.prior_for(task_class)
            .map(|e| e.recommended_initial)
            .ok_or_else(|| PolicyError::NoPrior(task_class.to_owned()))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn priors_exist_for_all_default_classes() {
        let table = default_table();
        assert_eq!(table.initial("concept_generation").unwrap(), 0.9);
        assert_eq!(table.initial("evaluation").unwrap(), 0.3);
        assert!(matches!(
            table.initial("unknown_class"),
            Err(PolicyError::NoPrior(_))
        ));
    }

    #[test]
    fn in_band_adjustment_passes_through() {
        let table = default_table();
        let adj = table
            .adjust("visual_critique", 0.5, "operator preference")
            .unwrap();
        assert_eq!(adj.selected, 0.5);
        assert_eq!(adj.band, Band::Moderate);
    }

    #[test]
    fn out_of_band_request_is_clamped_into_band() {
        let table = default_table();
        let adj = table
            .adjust("classification", 0.95, "agent asked for hot sampling")
            .unwrap();
        assert!(adj.band.contains(adj.selected));
        assert_eq!(adj.selected, 0.3); // clamped to Low band ceiling
        assert_eq!(adj.original, 0.95);
    }

    #[test]
    fn adjustment_is_loggable() {
        let table = default_table();
        let adj = table.adjust("concept_generation", 1.0, "creative").unwrap();
        let rendered = adj.to_string();
        assert!(rendered.contains("concept_generation"));
        assert!(rendered.contains("creative"));
    }

    #[test]
    fn table_is_serde_roundtrip() {
        let table = default_table();
        let back: PolicyTable =
            serde_json::from_str(&serde_json::to_string(&table).unwrap()).unwrap();
        assert_eq!(table, back);
    }
}

//! Loopback TAP transport (Gates 1 & 7 desktop-side).
//!
//! With no television in this environment, the "device" is simulated by a
//! loopback directory: frames are written one-per-file into `inbox/`, the
//! device side validates digests, reassembles contiguously, and acknowledges
//! into `acks/`. Everything uses tapestry-core's real Frame and
//! TransferState types, so swapping this for a socket later changes
//! transport only — not semantics.

use std::path::{Path, PathBuf};

use tapestry_core::ids::ArtifactId;
use tapestry_core::protocol::chunk::TransferState;
use tapestry_core::protocol::frame::Frame;
use tapestry_core::protocol::Channel;
use tapestry_core::{Result, TapestryError};

/// Directories for one loopback session.
#[derive(Debug, Clone)]
pub struct LoopbackTransport {
    inbox: PathBuf,
    acks: PathBuf,
}

impl LoopbackTransport {
    pub fn open(root: &Path) -> Result<Self> {
        let inbox = root.join("inbox");
        let acks = root.join("acks");
        std::fs::create_dir_all(&inbox).map_err(|e| io_err("inbox", &e))?;
        std::fs::create_dir_all(&acks).map_err(|e| io_err("acks", &e))?;
        Ok(Self { inbox, acks })
    }

    /// Sender side: chunk `payload` into TAP frames and write them.
    /// Frames are numbered by seq in file names for contiguity checks.
    pub fn send_artifact(
        &self,
        session: &tapestry_core::ids::SessionId,
        sender: &tapestry_core::ids::DeviceId,
        artifact: &ArtifactId,
        payload: &[u8],
    ) -> Result<Vec<Frame>> {
        let chunk_len = tapestry_core::protocol::frame::MAX_CHUNK_LEN;
        if payload.is_empty() {
            return Err(TapestryError::InvalidValue {
                field: "payload",
                reason: "refusing to transfer an empty artefact".into(),
            });
        }
        let mut frames = Vec::new();
        for (seq, offset) in (1u64..).zip((0..payload.len()).step_by(chunk_len as usize)) {
            let end = ((offset + chunk_len as usize).min(payload.len())) as u64;
            let mut frame = Frame::new(
                session.clone(),
                Channel::Artefact,
                "chunk",
                seq,
                sender.clone(),
                payload[offset..end as usize].to_vec(),
            );
            frame.artifact = Some(artifact.clone());
            frame.offset = Some(offset as u64);
            frame.validate()?;
            let path = self.inbox.join(format!("{artifact}-{seq:06}.frame.json"));
            std::fs::write(&path, frame.to_json()?)
                .map_err(|e| io_err(&path.display().to_string(), &e))?;
            frames.push(frame);
        }
        Ok(frames)
    }

    /// Device side: read inbox frames for one artefact, verify each digest,
    /// reassemble only over a contiguous prefix, and write acks. Returns the
    /// reassembled bytes, or an error naming the first bad frame.
    pub fn receive_artifact(&self, artifact: &ArtifactId) -> Result<Vec<u8>> {
        let mut frame_files: Vec<_> = std::fs::read_dir(&self.inbox)
            .map_err(|e| io_err("inbox", &e))?
            .flatten()
            .map(|e| e.path())
            .filter(|p| {
                p.file_name()
                    .and_then(|n| n.to_str())
                    .map(|n| n.starts_with(&format!("{artifact}-")) && n.ends_with(".frame.json"))
                    .unwrap_or(false)
            })
            .collect();
        frame_files.sort();

        let mut reassembled = Vec::new();
        let mut transfer: Option<TransferState> = None;
        for (expected_seq, path) in frame_files.iter().enumerate() {
            let bytes = std::fs::read(path).map_err(|e| io_err(&path.display().to_string(), &e))?;
            let frame = Frame::from_json(&bytes)?;
            frame.validate()?; // digest / size / schema checks

            // Contiguity: seq must be 1..N in order.
            if frame.seq != (expected_seq + 1) as u64 {
                return Err(TapestryError::IllegalTransition(format!(
                    "non-contiguous frame seq {} at position {}",
                    frame.seq, expected_seq
                )));
            }
            let offset = frame.offset.unwrap_or(0);
            if offset != reassembled.len() as u64 {
                return Err(TapestryError::IllegalTransition(format!(
                    "frame offset {offset} does not continue at {}",
                    reassembled.len()
                )));
            }

            let ack_path = self
                .acks
                .join(format!("{}-{:06}.ack.json", artifact, frame.seq));
            if transfer.as_ref().map(|t| t.total_len).unwrap_or(0) == 0 {
                // Total length is unknown until all frames arrive; acks are
                // per-chunk and the manifest check happens in `is_complete_check`.
            }
            reassembled.extend_from_slice(&frame.payload);
            let ack = tapestry_core::protocol::chunk::ChunkAck {
                artifact: artifact.clone(),
                offset,
                digest: frame.digest.clone(),
            };
            std::fs::write(&ack_path, serde_json::to_vec(&ack)?)
                .map_err(|e| io_err(&ack_path.display().to_string(), &e))?;
            let _ = &mut transfer;
        }
        Ok(reassembled)
    }

    /// Count acknowledgements written for an artefact.
    pub fn ack_count(&self, artifact: &ArtifactId) -> usize {
        std::fs::read_dir(&self.acks)
            .map(|rd| {
                rd.flatten()
                    .filter(|e| {
                        e.file_name()
                            .to_str()
                            .map(|n| {
                                n.starts_with(&format!("{artifact}-")) && n.ends_with(".ack.json")
                            })
                            .unwrap_or(false)
                    })
                    .count()
            })
            .unwrap_or(0)
    }
}

fn io_err(context: &str, e: &std::io::Error) -> TapestryError {
    TapestryError::IllegalTransition(format!("io failure at {context}: {e}"))
}

#[cfg(test)]
mod tests {
    use super::*;
    use tapestry_core::ids::{DeviceId, SessionId};

    fn setup() -> (tempfile::TempDir, LoopbackTransport) {
        let dir = tempfile::tempdir().unwrap();
        let transport = LoopbackTransport::open(dir.path()).unwrap();
        (dir, transport)
    }

    fn ids() -> (SessionId, DeviceId, ArtifactId) {
        (
            SessionId::generate(),
            DeviceId::generate(),
            ArtifactId::generate(),
        )
    }

    #[test]
    fn roundtrip_small_payload() {
        let (_dir, t) = setup();
        let (s, d, a) = ids();
        let payload = b"hello tapestry artefact".to_vec();
        let frames = t.send_artifact(&s, &d, &a, &payload).unwrap();
        assert_eq!(frames.len(), 1);
        let received = t.receive_artifact(&a).unwrap();
        assert_eq!(received, payload);
        assert_eq!(t.ack_count(&a), 1);
    }

    #[test]
    fn multi_chunk_reassembly_is_exact() {
        let (_dir, t) = setup();
        let (s, d, a) = ids();
        let payload: Vec<u8> = (0..(tapestry_core::protocol::frame::MAX_CHUNK_LEN * 2 + 7)
            as usize)
            .map(|i| (i % 251) as u8)
            .collect();
        let frames = t.send_artifact(&s, &d, &a, &payload).unwrap();
        assert_eq!(frames.len(), 3);
        let received = t.receive_artifact(&a).unwrap();
        assert_eq!(received, payload);
        assert_eq!(t.ack_count(&a), 3);
    }

    #[test]
    fn corrupted_frame_is_rejected() {
        let (_dir, t) = setup();
        let (s, d, a) = ids();
        t.send_artifact(&s, &d, &a, b"data").unwrap();
        // Tamper with the frame on disk.
        let frame_path = std::fs::read_dir(&t.inbox)
            .unwrap()
            .next()
            .unwrap()
            .unwrap()
            .path();
        let mut json: serde_json::Value =
            serde_json::from_slice(&std::fs::read(&frame_path).unwrap()).unwrap();
        json["payload"] = serde_json::Value::Array(vec![serde_json::json!(255)]);
        std::fs::write(&frame_path, serde_json::to_vec(&json).unwrap()).unwrap();
        assert!(t.receive_artifact(&a).is_err());
        assert_eq!(t.ack_count(&a), 0);
    }

    #[test]
    fn empty_payload_is_rejected_by_validation() {
        let (_dir, t) = setup();
        let (s, d, a) = ids();
        assert!(t.send_artifact(&s, &d, &a, b"").is_err());
    }
}

//! End-to-end acceptance: `tapestry "prompt"` drives the complete loop —
//! auth → playbook drive → artefacts → loopback TAP transfer with digest
//! verification → human review → knowledge journal → structured completion.
//! Run against the built binary with an isolated TAPESTRY_DATA.

use std::io::Write;
use std::process::{Command, Stdio};

/// Locate the `tapestry` binary next to the test executable.
fn binary_path() -> std::path::PathBuf {
    let mut p = std::env::current_exe().unwrap();
    while p.pop() {
        let candidate = p.join("tapestry");
        if candidate.exists() {
            return candidate;
        }
    }
    panic!("tapestry binary not found near test executable");
}

#[test]
fn full_loop_approve() {
    let bin = binary_path();
    let data = tempfile::tempdir().unwrap();
    let mut child = Command::new(&bin)
        .arg("Generate four visual concepts for the Tapestry home screen")
        .env("TAPESTRY_DATA", data.path())
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("spawn tapestry binary");
    child
        .stdin
        .as_mut()
        .unwrap()
        .write_all(b"APPROVE\n")
        .unwrap();
    let output = child.wait_with_output().unwrap();

    assert_eq!(
        output.status.code(),
        Some(0),
        "stderr: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    let stdout = String::from_utf8_lossy(&output.stdout);
    assert!(stdout.contains("TAPESTRY COMPLETE"), "stdout: {stdout}");
    assert!(stdout.contains("decision    approved"));
    assert!(stdout.contains("session     tap_"));
    assert!(stdout.contains("device      lounge-loopback"));

    // Knowledge journal recorded session + artefacts + human decision.
    let journal = std::fs::read_to_string(data.path().join("knowledge/tapestry.jsonl")).unwrap();
    assert!(journal.contains("\"kind\":\"session\""));
    assert!(journal.contains("\"kind\":\"artefact\""));
    assert!(journal.contains("explicit_human_judgement"));

    // Playbook drive evidence exists.
    let drives = std::fs::read_dir(data.path().join("drives"))
        .unwrap()
        .count();
    assert!(drives >= 1);

    // Loopback transfer evidence: frames + acks.
    let transport_root = std::fs::read_dir(data.path().join("transport"))
        .unwrap()
        .count();
    assert!(transport_root >= 1);
}

#[test]
fn full_loop_reject_exits_nonzero() {
    let bin = binary_path();
    let data = tempfile::tempdir().unwrap();
    let mut child = Command::new(&bin)
        .arg("make it darker")
        .env("TAPESTRY_DATA", data.path())
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .unwrap();
    child
        .stdin
        .as_mut()
        .unwrap()
        .write_all(b"REJECT\n")
        .unwrap();
    let output = child.wait_with_output().unwrap();
    assert_eq!(
        output.status.code(),
        Some(5),
        "review rejection must exit 5"
    );
    let stdout = String::from_utf8_lossy(&output.stdout);
    assert!(stdout.contains("decision    rejected"));
}

#[test]
fn doctor_reports_healthy_after_run() {
    let bin = binary_path();
    let data = tempfile::tempdir().unwrap();
    // Prime the data dir with one run.
    let mut child = Command::new(&bin)
        .arg("prime")
        .env("TAPESTRY_DATA", data.path())
        .stdin(Stdio::piped())
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn()
        .unwrap();
    child
        .stdin
        .as_mut()
        .unwrap()
        .write_all(b"APPROVE\n")
        .unwrap();
    child.wait().unwrap();

    let out = Command::new(&bin)
        .arg("doctor")
        .env("TAPESTRY_DATA", data.path())
        .output()
        .unwrap();
    assert_eq!(out.status.code(), Some(0));
    let stdout = String::from_utf8_lossy(&out.stdout);
    assert!(stdout.contains("vault"));
    assert!(stdout.contains("transport"));
    assert!(stdout.contains("knowledge"));
    assert!(stdout.contains("pressure"));
}
